/* rdfvm.h - interpreter for the room scripts.
 *
 * The .rdf files of the away team's rooms (DATA.001) carry their scripts as
 * 16-bit x86 machine code, generated by a script compiler: a handful of
 * instructions that test and set bytes of the room state (SI points at it),
 * keep variables in the file itself (CS-relative), and call the game through
 * the far pointer at the start of the file with the arguments on the stack.
 * The code is data, so it cannot be ported; this runs it.
 */

#ifndef RDFVM_H
#define RDFVM_H

#include "compat.h"

/* Where the room state sits in the scripts' data segment. The .rdf holds
 * this address (rdf->state), and the scripts load SI from it. */
#define RDF_ROOM_BASE   0x0100

/* The game call: the six words at the top of the script's stack are the
 * arguments (the first is the command).  Returns the 32 bit result (DX:AX). */
typedef int32_t (*RdfService)(int16_t *args);

/* Run the script at offset entry of the .rdf image (size bytes) until it
 * returns, 0 if it did.  room is the RoomState the script sees at
 * RDF_ROOM_BASE.  A script that does what the real machine would have
 * crashed on (stack under/overflow, wild accesses) stops with 1. */
int RdfRun(unsigned char *image, uint32_t size, uint16_t entry, void *room, uint16_t room_size,
           RdfService service);

/* Why the last RdfRun failed (0 returned there if it went well). */
const char *RdfError(uint16_t *ip);

/* Check that every instruction reachable from entry is one RdfRun can
 * execute and stays inside the image.  Returns 0 if so, else the offset of
 * the first offender. */
int RdfVerify(unsigned char *image, uint32_t size, uint16_t entry);

#endif
